function legacyTickets(picks){return [5,10,20].map(target=>{const usable=picks.filter(p=>p.odds&&Date.parse(p.start)>Date.now()).slice(0,22);let best=null,states=[{legs:[],odds:1,probability:1}];for(const p of usable){const next=[...states];for(const state of states){if(state.legs.length>=10||state.legs.some(l=>l.eventId===p.eventId))continue;const candidate={legs:[...state.legs,p],odds:state.odds*p.odds,probability:state.probability*p.probability};if(candidate.odds>target*1.15)continue;if(candidate.odds>=target*.95){if(!best||candidate.probability>best.probability)best=candidate}else next.push(candidate)}const bins=new Map();for(const state of next){const key=state.legs.length+':'+Math.round(Math.log(state.odds)*100);if(!bins.has(key)||state.probability>bins.get(key).probability)bins.set(key,state)}states=[...bins.values()]}return best?{target,...best}:{target,legs:[],odds:0,probability:0}})}
