const nowISO=()=>new Date().toISOString();
const validURL=x=>{try{return new URL(x).protocol==='https:'}catch{return false}};
const finite=x=>typeof x==='number'&&Number.isFinite(x);
const norm=x=>String(x).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/[^a-z0-9]/g,'');
const fixtureKey=f=>[f.sport,norm(f.home.name),norm(f.away.name),f.start].join('|');
const recordKey=id=>'research/records/'+encodeURIComponent(id)+'.json';
async function readJSON(env,key){const v=await env.BUCKET?.get(key);return v?await v.json():null}
async function entries(env,prefix){if(!env.BUCKET)return [];let cursor,objects=[];do{const r=await env.BUCKET.list({prefix,limit:1000,...(cursor?{cursor}:{})});objects.push(...r.objects);cursor=r.truncated?r.cursor:null}while(cursor);return objects}
async function allRecords(env){const keys=await entries(env,'research/records/');return (await pool(keys,x=>readJSON(env,x.key),8)).filter(x=>x?.id)}
function availableMeans(a){return Object.fromEntries(['shots','shotsOnTarget','yellowCards','redCards'].map(k=>{const valid=a.map(r=>r[k]).filter(finite);return [k,{mean:valid.length?mean(valid):null,sample:valid.length}]}))}
const auditedStats=a=>a.length?{...stats(a),availableMetrics:availableMeans(a),home:undefined,away:undefined,draws:rate(a,x=>x.result==='D'),losses:rate(a,x=>x.result==='L'),from:a.at(-1).date,to:a[0].date}:null;
function allowedResult(m,sport){return (m.matchResults||[]).find(r=>r.resultTypeID===2&&(sport!=='Football'||r.resultTypeKind==='After90Minutes'))}
function openHistory(ms,id,before,sport,url){return ms.filter(m=>m.matchIsFinished&&Date.parse(m.matchDateTimeUTC)<before&&Date.parse(m.matchDateTimeUTC)>before-365*86400000&&[m.team1.teamId,m.team2.teamId].includes(id)).flatMap(m=>{const r=allowedResult(m,sport);if(!r||!finite(r.pointsTeam1)||!finite(r.pointsTeam2))return [];const home=m.team1.teamId===id,gf=home?r.pointsTeam1:r.pointsTeam2,ga=home?r.pointsTeam2:r.pointsTeam1;return [{id:String(m.matchID),date:m.matchDateTimeUTC,gf,ga,total:gf+ga,venue:home?'home':'away',opponent:(home?m.team2:m.team1).teamName,opponentId:(home?m.team2:m.team1).teamId,result:gf>ga?'W':gf<ga?'L':'D',competition:m.leagueName,season:m.leagueSeason,url,scoreScope:sport==='Football'?'regulation':'source final; overtime detail unavailable'}]}).sort((a,b)=>Date.parse(b.date)-Date.parse(a.date))}
const SUPPORTED=[['bl1','Football'],['bl2','Football'],['la1','Football'],['pl','Football'],['ucl','Football'],['uel2026','Football'],['uecl2026','Football'],['bl3','Football'],['del','Ice hockey'],['DEL2','Ice hockey'],['CHL','Ice hockey'],['OLN','Ice hockey']];
async function sportsDBFixtures(env,date){
 const fixtures=[],coverage=[];
 // WAT spans two UTC dates. Query both without dropping started fixtures from inventory.
 const dates=[new Date(Date.parse(date+'T00:00:00+01:00')).toISOString().slice(0,10),date];
 for(const sport of ['Basketball','Handball','Ice hockey']){
  let count=0,failed=false;
  for(const d of dates){const url='https://www.thesportsdb.com/api/v1/json/123/eventsday.php?d='+d+'&s='+encodeURIComponent(sport==='Ice hockey'?'Ice Hockey':sport);
   try{const data=await getData(url,env,1800000);if(!('events' in data))throw Error('Invalid fixture response');
    for(const e of data.events||[]){const start=e.strTimestamp?(e.strTimestamp.endsWith('Z')||/[+-]\d\d:\d\d$/.test(e.strTimestamp)?e.strTimestamp:e.strTimestamp+'Z'):e.dateEvent&&e.strTime?e.dateEvent+'T'+e.strTime+'Z':null;
     if(!start||!Number.isFinite(Date.parse(start))||day(new Date(start))!==date||!e.strHomeTeam||!e.strAwayTeam)continue;
     fixtures.push({eventId:'tsdb-'+e.idEvent,sport,league:e.strLeague||'Competition unavailable',start,status:e.intHomeScore!=null&&e.intAwayScore!=null?'post':Date.parse(start)>Date.now()?'pre':'unknown',home:{id:e.idHomeTeam,name:e.strHomeTeam},away:{id:e.idAwayTeam,name:e.strAwayTeam},match:e.strHomeTeam+' — '+e.strAwayTeam,history:{home:[],away:[]},sources:[{url,retrievedAt:nowISO(),classification:'SOURCE_REPORTED',cacheMaxAgeMinutes:30}],scope:'TheSportsDB free fixture feed; capped at 3 events per UTC day per sport. Not a complete schedule. Statistical research pending.'});count++;
    }
   }catch(e){failed=true;coverage.push({sport,league:'TheSportsDB '+d,status:'failed',reason:e.message,url})}
  }
  coverage.push({sport,league:'TheSportsDB daily fixtures',status:failed?'partial':'limited',fixtures:count,reason:'Free feed returns at most 3 events per UTC day per sport. Incomplete league coverage; no odds or statistical model supplied.',url:'https://www.thesportsdb.com/docs_api_guide.php'});
 }
 return {fixtures:[...new Map(fixtures.map(f=>[f.eventId,f])).values()],coverage};
}
async function discover(env,date=day(),limit=10000,includeRoot=true){const season=new Date().getUTCFullYear()-(new Date().getUTCMonth()<6?1:0),fixtures=[],coverage=[],datasets=[];await pool(SUPPORTED,async([key,sport])=>{const url='https://api.openligadb.de/getmatchdata/'+key+'/'+season;try{const ms=await getData(url,env,15*60000);if(!Array.isArray(ms))throw Error('Invalid source response');const cached=await readJSON(env,'http/'+encodeURIComponent(url));const observed=cached?.at?new Date(cached.at).toISOString():nowISO();datasets.push({ms,sport,url,observed});const upcoming=ms.filter(m=>!m.matchIsFinished&&Date.parse(m.matchDateTimeUTC)>Date.now()&&day(new Date(m.matchDateTimeUTC))===date);coverage.push({sport,league:ms[0]?.leagueName||key,status:'connected',fixtures:upcoming.length,url,retrievedAt:observed});for(const m of upcoming){const f={eventId:'ol-'+m.matchID,sport,league:m.leagueName,start:m.matchDateTimeUTC,status:'pre',home:{id:m.team1.teamId,name:m.team1.teamName},away:{id:m.team2.teamId,name:m.team2.teamName},match:m.team1.teamName+' — '+m.team2.teamName,season,sourceKey:key,sources:[{url,retrievedAt:observed,classification:'SOURCE_REPORTED',cacheMaxAgeMinutes:15}],history:{home:openHistory(ms,m.team1.teamId,Date.now(),sport,url).slice(0,10),away:openHistory(ms,m.team2.teamId,Date.now(),sport,url).slice(0,10)},seasonStats:{home:auditedStats(openHistory(ms,m.team1.teamId,Date.now(),sport,url)),away:auditedStats(openHistory(ms,m.team2.teamId,Date.now(),sport,url))}};fixtures.push(f)}}catch(e){coverage.push({sport,league:key,status:'failed',reason:e.message,url,retrievedAt:nowISO()})}},4);
const extra=includeRoot?await sportsDBFixtures(env,date):{fixtures:[],coverage:[]};fixtures.push(...extra.fixtures);coverage.push(...extra.coverage);
// Previous-season fallback uses the same competition; no friendlies or future results.
const unique=[...new Map(fixtures.map(f=>[fixtureKey(f),f])).values()];const batch=unique.sort((a,b)=>Date.parse(a.start)-Date.parse(b.start)).slice(0,limit);for(const f of batch){for(const side of ['home','away'])f.history[side]=[...new Map(datasets.filter(d=>d.sport===f.sport).flatMap(d=>openHistory(d.ms,f[side].id,Date.now(),f.sport,d.url)).map(r=>[r.id,r])).values()].sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)).slice(0,10);for(const d of datasets.filter(d=>d.sport===f.sport&&f.history.home.concat(f.history.away).some(r=>r.url===d.url)))if(!f.sources.some(x=>x.url===d.url))f.sources.push({url:d.url,retrievedAt:d.observed,classification:'SOURCE_REPORTED',cacheMaxAgeMinutes:15});const ds=datasets.find(d=>d.url===f.sources[0].url);const completed=ds?.ms.filter(m=>m.matchIsFinished).map(m=>allowedResult(m,f.sport)).filter(r=>r&&finite(r.pointsTeam1)&&finite(r.pointsTeam2))||[];f.leagueEnvironment={matches:completed.length,meanTotal:completed.length?mean(completed.map(r=>r.pointsTeam1+r.pointsTeam2)):null,scope:'Current season same competition; source-reported completed scores'};}await pool(batch,async f=>{if(!f.sourceKey||f.history.home.length>=10&&f.history.away.length>=10)return;const url='https://api.openligadb.de/getmatchdata/'+f.sourceKey+'/'+(season-1);try{const ms=await getData(url,env,86400000);for(const side of ['home','away'])f.history[side]=[...new Map([...f.history[side],...openHistory(ms,f[side].id,Date.now(),f.sport,url)].map(r=>[r.id,r])).values()].sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)).slice(0,10);const cached=await readJSON(env,'http/'+encodeURIComponent(url));f.sources.push({url,retrievedAt:cached?.at?new Date(cached.at).toISOString():nowISO(),classification:'SOURCE_REPORTED',cacheMaxAgeMinutes:1440})}catch(e){f.fallbackError=e.message}},4);
const footballData=await footballHistoryData(env);for(const f of batch.filter(f=>f.sport==='Football'))for(const side of ['home','away']){for(const dataset of footballData){const h=footballHistory(dataset.rows,f[side].name,Date.now(),dataset.url);if(h.length>f.history[side].length){f.history[side]=h;if(!f.sources.some(s=>s.url===dataset.url))f.sources.push({url:dataset.url,retrievedAt:dataset.retrievedAt,classification:'SOURCE_REPORTED',cacheMaxAgeMinutes:5760});f.scope='Available OpenLigaDB competition results and Football-Data.co.uk domestic full-time scores, exact normalized team-name mapping; last 10 when available, minimum 6 for a forecast. Current-season-only domestic fallback; incomplete competition coverage.'}}}return {fixtures:batch,discovered:unique.length,coverage};}
