let sourceNextAt=0,sourceBlockedUntil=0;
async function tsdbData(url,env,ttl=1800000){
 const cached=await readJSON(env,'http/'+encodeURIComponent(url));if(cached&&Date.now()-cached.at<ttl)return {data:cached.data,at:new Date(cached.at).toISOString()};
 if(Date.now()<sourceBlockedUntil)throw Error('TheSportsDB rate limit: retry after '+new Date(sourceBlockedUntil).toISOString());
 const wait=sourceNextAt-Date.now();if(wait>0)await new Promise(r=>setTimeout(r,wait));sourceNextAt=Date.now()+2300;
 try{const data=await getData(url,env,ttl);const receipt=await readJSON(env,'http/'+encodeURIComponent(url));return {data,at:receipt?new Date(receipt.at).toISOString():nowISO()}}catch(e){if(/429/.test(e.message))sourceBlockedUntil=Date.now()+65000;throw e}
}
function tsdbStart(e){const t=e.strTimestamp|| (e.dateEvent&&e.strTime?e.dateEvent+'T'+e.strTime:null);if(!t)return null;const iso=/Z$|[+-]\d\d:\d\d$/.test(t)?t:t+'Z';return Number.isFinite(Date.parse(iso))?iso:null}
function tsdbHistory(events,id,before,url){return [...new Map(events.filter(e=>e.intHomeScore!==null&&e.intHomeScore!==''&&e.intAwayScore!==null&&e.intAwayScore!==''&&Number.isFinite(Number(e.intHomeScore))&&Number.isFinite(Number(e.intAwayScore))&&['Match Finished','FT','AOT','AET','AP'].includes(e.strStatus)&&[e.idHomeTeam,e.idAwayTeam].map(String).includes(String(id))&&tsdbStart(e)&&Date.parse(tsdbStart(e))<before&&Date.parse(tsdbStart(e))>before-365*86400000).map(e=>{const home=String(e.idHomeTeam)===String(id),gf=Number(home?e.intHomeScore:e.intAwayScore),ga=Number(home?e.intAwayScore:e.intHomeScore);return {id:'tsdb-'+e.idEvent,date:tsdbStart(e),gf,ga,total:gf+ga,venue:home?'home':'away',opponent:home?e.strAwayTeam:e.strHomeTeam,opponentId:home?e.idAwayTeam:e.idHomeTeam,result:gf>ga?'W':gf<ga?'L':'D',url:e._source||url,scoreScope:'Source final score; regulation / overtime not independently confirmed'}}).map(r=>[r.id,r])).values()].sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)).slice(0,10)}
async function collectLeague(env,date,l){
 const dates=[new Date(Date.parse(date+'T00:00:00+01:00')).toISOString().slice(0,10),date],events=[],sources=[],coverage=[];
 for(const d of dates){const url='https://www.thesportsdb.com/api/v1/json/123/eventsday.php?d='+d+'&l='+l.id;try{const res=await tsdbData(url,env);if(!('events' in res.data))throw Error('Invalid daily fixture response');events.push(...(res.data.events||[]).map(e=>({...e,_source:url,_retrievedAt:res.at}))); sources.push({url,retrievedAt:res.at,classification:'SOURCE_REPORTED',cacheMaxAgeMinutes:30});coverage.push({date,sport:l.sport,league:l.name,status:(res.data.events||[]).length>=3?'limited':'connected',fixtures:(res.data.events||[]).filter(e=>tsdbStart(e)&&day(new Date(tsdbStart(e)))===date).length,url,retrievedAt:res.at,reason:'League-filtered free feed; at most 3 events per UTC day. A successful response does not prove completeness.'})}catch(e){coverage.push({date,sport:l.sport,league:l.name,status:'failed',url,reason:e.message})}}
 const upcoming=[...new Map(events.filter(e=>String(e.idLeague)===String(l.id)&&tsdbStart(e)&&day(new Date(tsdbStart(e)))===date&&Date.parse(tsdbStart(e))>Date.now()&&!['Match Finished','FT','AOT','AET','AP','Postponed','Cancelled'].includes(e.strStatus)&&e.strHomeTeam&&e.strAwayTeam).map(e=>[e.idEvent,e])).values()];
 const ledgerKey='research/source-events/'+l.id+'.json',old=await readJSON(env,ledgerKey)||[];let scores=[...old,...events];
 if(upcoming.length){const season=l.season||String(new Date().getUTCFullYear());const url='https://www.thesportsdb.com/api/v1/json/123/eventsseason.php?id='+l.id+'&s='+encodeURIComponent(season);try{const res=await tsdbData(url,env,86400000);scores.push(...(res.data.events||[]).map(e=>({...e,_source:url,_retrievedAt:res.at}))); sources.push({url,retrievedAt:res.at,classification:'SOURCE_REPORTED',cacheMaxAgeMinutes:1440})}catch(e){coverage.push({date,sport:l.sport,league:l.name,status:'history_failed',reason:e.message,url})}}
 scores=[...new Map(scores.map(e=>[e.idEvent,e])).values()];await env.BUCKET.put(ledgerKey,JSON.stringify(scores.filter(e=>tsdbStart(e)&&Date.parse(tsdbStart(e))>Date.now()-365*86400000)));
 const records=[];for(const e of upcoming){const start=tsdbStart(e),historyURL=sources.find(x=>x.url.includes('eventsseason'))?.url||sources[0]?.url,history={home:tsdbHistory(scores,e.idHomeTeam,Date.now(),historyURL),away:tsdbHistory(scores,e.idAwayTeam,Date.now(),historyURL)};for(const x of scores)if(x._source&&!sources.some(s=>s.url===x._source))sources.push({url:x._source,retrievedAt:x._retrievedAt,classification:'SOURCE_REPORTED',cacheMaxAgeMinutes:1440});const f={eventId:'tsdb-'+e.idEvent,sport:l.sport,league:l.name,start,status:'pre',home:{id:e.idHomeTeam,name:e.strHomeTeam},away:{id:e.idAwayTeam,name:e.strAwayTeam},match:e.strHomeTeam+' — '+e.strAwayTeam,season:l.season,history,sources,scope:'TheSportsDB league-filtered fixtures plus available season scores and accumulated score archive. Free daily responses cap at 3 per league per UTC day; season responses cap at 15. Incomplete sample; final-score settlement unverified.'};records.push(await saveResearch(env,{...buildResearch(f),generatedByScan:true},{fromScan:true}))}
 await env.BUCKET.put('research/coverage/'+date+'/'+l.id+'.json',JSON.stringify({date,league:l.name,sport:l.sport,entries:coverage,updated:nowISO()}));return {records,coverage};
}
async function collectBatch(env,date,cursor=0){const batch=COLLECTION_LEAGUES.slice(cursor,cursor+2),records=[],coverage=[];for(const l of batch){const result=await collectLeague(env,date,l);records.push(...result.records);coverage.push(...result.coverage)}return {date,cursor,nextCursor:cursor+batch.length<COLLECTION_LEAGUES.length?cursor+batch.length:null,totalLeagues:COLLECTION_LEAGUES.length,records:records.map(r=>({id:r.id,match:r.match,forecast:r.forecast})),coverage,updated:nowISO()}}
async function coverageFor(env,date){const keys=await entries(env,'research/coverage/'+date+'/');return (await pool(keys,k=>readJSON(env,k.key))).filter(Boolean).flatMap(x=>x.entries||[])}

const FOOTBALL_FILES=[['E0','England'],['SP1','Spain'],['D1','Germany'],['I1','Italy'],['F1','France'],['N1','Netherlands'],['P1','Portugal'],['B1','Belgium'],['SC0','Scotland'],['T1','Turkey'],['G1','Greece']];
function csvRows(text){const rows=[];let row=[],field='',quote=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quote&&text[i+1]==='"'){field+='"';i++}else quote=!quote}else if(c===','&&!quote){row.push(field);field=''}else if(c==='\n'&&!quote){row.push(field.replace(/\r$/,''));rows.push(row);row=[];field=''}else field+=c}if(field||row.length){row.push(field.replace(/\r$/,''));rows.push(row)}const names=rows.shift()||[];return rows.map(r=>Object.fromEntries(names.map((n,i)=>[n.replace(/^\ufeff/,''),r[i]??''])))}
const TEAM_ALIASES={'como1907':'como','galatasarayistanbul':'galatasaray','lilleosc':'lille','rclens':'lens','brugge':'club brugge','feyenoordrotterdam':'feyenoord','heartofmidlothian':'hearts','twenteenschede':'twente','rscanderlecht':'anderlecht','necnijmegen':'nijmegen','olympiquelyon':'lyon','ofikreta':'ofi crete','bayer04leverkusen':'leverkusen','tsghoffenheim':'hoffenheim','juventusturin':'juventus','staderennes':'rennes','acmailand':'milan','besiktasistanbul':'besiktas','celticglasgow':'celtic','celtavigo':'celta','olympiquemarseille':'marseille','benficalissabon':'benfica','ajaxamsterdam':'ajax','atalantabergamo':'atalanta','sportingbraga':'sp braga','kaagent':'gent','vvsinttruiden':'st truiden','mailand':'milan','bayernmunchen':'bayern munich','manchesterunited':'man united','brightonhovealbion':'brighton','parissaintgermain':'paris sg','intermailand':'inter','fcbrugge':'club brugge','realbetis':'betis','rbleipzig':'rb leipzig','athleticclub':'ath bilbao','fcgetafe':'getafe'};
function teamNameKey(name){let n=String(name).normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/\./g,'').replace(/\b(fc|afc|f\.c\.|cf|ac|as|sc|sv)\b/g,'').replace(/[^a-z0-9]/g,'');const value=TEAM_ALIASES[n];return value?value.replace(/[^a-z0-9]/g,''):n}
function footballHistory(rows,name,before,url){const id=teamNameKey(name);return rows.filter(r=>r.HomeTeam&&r.AwayTeam&&[teamNameKey(r.HomeTeam),teamNameKey(r.AwayTeam)].includes(id)&&/^\d+$/.test(r.FTHG)&&/^\d+$/.test(r.FTAG)).flatMap(r=>{const parts=r.Date.split('/');if(parts.length!==3)return [];const year=parts[2].length===2?'20'+parts[2]:parts[2],date=year+'-'+parts[1].padStart(2,'0')+'-'+parts[0].padStart(2,'0')+'T'+(/^\d\d:\d\d$/.test(r.Time)?r.Time:'12:00')+':00Z';if(!Number.isFinite(Date.parse(date))||Date.parse(date)>=before||Date.parse(date)<before-365*86400000)return [];const home=teamNameKey(r.HomeTeam)===id,gf=Number(home?r.FTHG:r.FTAG),ga=Number(home?r.FTAG:r.FTHG),number=x=>x!==''&&Number.isFinite(Number(x))?Number(x):null;return [{id:'fd-'+r.Date+'-'+teamNameKey(r.HomeTeam)+'-'+teamNameKey(r.AwayTeam),date,gf,ga,total:gf+ga,venue:home?'home':'away',opponent:home?r.AwayTeam:r.HomeTeam,opponentId:teamNameKey(home?r.AwayTeam:r.HomeTeam),result:gf>ga?'W':gf<ga?'L':'D',shots:number(home?r.HS:r.AS),shotsOnTarget:number(home?r.HST:r.AST),yellowCards:number(home?r.HY:r.AY),redCards:number(home?r.HR:r.AR),url,scoreScope:'Source-reported domestic league full-time result',timeScope:'CSV kickoff used as reported; source timezone not independently confirmed'}]}).sort((a,b)=>Date.parse(b.date)-Date.parse(a.date)).slice(0,10)}
async function footballHistoryData(env){const out=[],current=new Date().getUTCFullYear()-(new Date().getUTCMonth()<6?1:0),season=String(current).slice(-2)+String(current+1).slice(-2);for(const[code,country]of FOOTBALL_FILES){const url='https://www.football-data.co.uk/mmz4281/'+season+'/'+code+'.csv',key='football-history/'+season+'/'+code;let cached=await readJSON(env,key);if(!cached||Date.now()-(cached.lastAttemptAt||cached.at)>=4*86400000){try{const res=await fetch(url,{signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error('HTTP '+res.status);const text=await res.text();if(!text.includes('HomeTeam')||!text.includes('FTHG'))throw Error('Invalid CSV response');cached={at:Date.now(),lastAttemptAt:Date.now(),rows:csvRows(text),url,country};await env.BUCKET.put(key,JSON.stringify(cached))}catch(e){cached={...(cached||{}),at:cached?.at||Date.now(),lastAttemptAt:Date.now(),url,country,error:e.message};await env.BUCKET.put(key,JSON.stringify(cached))}}if(cached?.rows)out.push({...cached,retrievedAt:new Date(cached.at).toISOString()})}return out}

function forecastFrom(r){
 if(!r.projection||r.homeSample<6||r.awaySample<6)return null;
 const markets=(r.markets||[]).filter(m=>m.verdict!=='KILL'&&finite(m.probability)&&m.probability>.5&&m.probability<1);
 markets.sort((a,b)=>b.probability-a.probability);const m=markets[0];if(!m)return null;
 const label=m.type==='total'?(m.side==='over'?'Over ':'Under ')+m.line+(r.sport==='Basketball'?' points':' goals'):m.type==='double_chance'?'Double chance '+m.side:m.type==='btts'?'Both teams to score: '+m.side:(m.side==='home'?r.home.name:r.away.name)+' to win';
 return {...m,selection:label,modelVersion:VERSION+(r.venueContext?.neutral===true&&validURL(r.venueContext?.sourceURL)?'-neutral-v1':''),classification:'EXPERIMENTAL_FORECAST',calibrated:false,odds:null,estimatedEV:null,referenceLineOnly:m.type==='total',reason:'Score-history baseline, not a calibrated betting recommendation. Reference lines are not verified bookmaker offers.',createdAt:nowISO()};
}
function baselineOtherSport(f,h,a){
 if(!['Basketball','Handball','Ice hockey'].includes(f.sport)||h.length<6||a.length<6)return null;
 const neutral=f.venueContext?.neutral===true&&validURL(f.venueContext?.sourceURL);
 const component=(rows,key,venue)=>neutral?mean(rows.map(r=>r[key])):blended(rows,key,venue);
 const home=(component(h,'gf','home')+component(a,'ga','away'))/2,away=(component(a,'gf','away')+component(h,'ga','home'))/2,total=home+away;
 const floor=f.sport==='Basketball'?14:f.sport==='Handball'?5:2;
 const sd=Math.max(floor,Math.sqrt(variance([...h,...a].map(x=>x.total))));
 const marginSD=Math.max(floor,Math.sqrt(variance([...h,...a].map(x=>x.gf-x.ga))));
 const markets=[],add=(type,side,line,p)=>markets.push({type,side,...(line==null?{}:{line}),period:'source_final',settlement:'unverified',probability:p,fairOdds:1/p,odds:null,estimatedEV:null,calibrated:false,verdict:'RESEARCH ONLY',reason:'Score-only exploratory baseline; overtime and offered line unverified'});
 if(f.sport==='Ice hockey'){for(const line of [4.5,5.5,6.5]){const p=1-cdf(Math.floor(line),total);add('total','over',line,p);add('total','under',line,1-p)}}
 else {const centre=Math.floor(total)+.5;for(const line of [centre-sd*.5,centre,centre+sd*.5].map(x=>Math.floor(x)+.5)){const p=1-normal((line-total)/sd);add('total','over',line,p);add('total','under',line,1-p)}const win=normal((home-away)/marginSD);add('win','home',null,win);add('win','away',null,1-win)}
 return {projection:{classification:'MODELLED',home,away,total,sd,calibrated:false,range:null,rangeReason:'No validated predictive interval',method:f.sport==='Ice hockey'?'Score-only independent Poisson total baseline; no goalie or special-team adjustment':'Score-only normal total and margin baseline; empirical variance floor; no possession or efficiency adjustment'},markets};
}
